{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C22", "C23"],
  "contradictory_card_ids": ["C52", "C66", "C67", "C62", "C60", "C64", "C69", "C63", "C65", "C61", "C59"],
  "prediction_basis_card_ids": ["C22", "C23"],
  "claims": [
    {
      "claim": "Oral rifampicin exposure records show substantial systemic exposure after standard oral dosing: model-estimated AUC0-24h of 40.8 mg·h/L in pregnant women and Cmax of 9.0 mg/L in postpartum women after ~10 mg/kg daily, supporting F >= 20%.",
      "card_ids": ["C22", "C23"]
    },
    {
      "claim": "C52 identifies rifampicin as a P-gp substrate, but P-gp efflux status is mechanistic and does not by itself establish F < 20%.",
      "card_ids": ["C52"]
    },
    {
      "claim": "L6 hepatic-clearance records for the rifapentine-like reference (RMB043) show moderate human microsomal intrinsic clearance (83 µL/min/mg), hepatic extraction ratio 0.4, and half-life 85 min, indicating some hepatic first-pass loss but not an affirmative F < 20% outcome for rifampicin.",
      "card_ids": ["C66", "C67", "C62", "C60", "C64", "C69"]
    },
    {
      "claim": "Rifabutin and rifalazil CYP3A4 metabolism records (C63, C65, C61) and the rifamycin-ethanol metabolism record (C59) are for other rifamycins and are not threshold-relevant direct rifampicin F evidence.",
      "card_ids": ["C63", "C65", "C61", "C59"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C66", "C67", "C62", "C60", "C64", "C69"]
    },
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C63", "C65", "C61"]
    },
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C59"]
    },
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C58"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for rifampicin in the supplied cards.",
    "No matched oral-versus-IV comparator for rifampicin or a close analog.",
    "L6 hepatic-clearance records are for rifapentine-like RMB043, rifabutin, rifalazil, rifamycin SV, and mycophenolic acid, not for rifampicin itself.",
    "C22/C23 are oral-exposure records, not dose-normalized F values.",
    "The low physicochemical prior is descriptor-based and cannot by itself establish F < 20%."
  ],
  "decision_summary": "Prediction remains high. L6 adds hepatic-clearance and metabolic-stability records for related rifamycins, including moderate hepatic extraction for the rifapentine-like reference, but none is a direct rifampicin F measurement or affirmatively establishes F < 20%. C22/C23 oral rifampicin exposure remains the strongest direction, so the high prediction is kept with moderate confidence."
}

